import {questions,edges,networkNodes,integrated,plan} from './exam-data.mjs';
import {clone,writeMol,parseMol,compareGraphs,checkArrowSet,checkReagents} from './chem-core.mjs';
import {moleculeSVG,ElectronCanvas} from './chem-svg.mjs';
import {StructureEditor} from './editor-bridge.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='or-studio-v1';
const empty=()=>({version:1,chapter:19,edges:{},tasks:{},paper:{},lectureMasks:{},ui:{view:'map',edge:'grignard-acid',task:'product-acyl'},updated:null});
function load(){try{const s=JSON.parse(localStorage.getItem(KEY));if(s?.version===1&&s.edges&&s.tasks&&s.paper&&s.lectureMasks&&s.ui)return s}catch{}return empty()}
let state=load(),view='map',currentTask=null,stepIndex=0,editor=null,arrowCanvas=null,taskGeneration=0,storageWarned=false,focusedCondition=0;
let lectureDoc=null,lectureFile=null,lecturePage=35,lectureRevealed=false,lectureDrawing=true,lectureRenderTask=null,lectureLoading=false;
function save(){state.updated=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));const p=$('#save-status');if(p)p.textContent='Saved on this device';}catch{if(!storageWarned){storageWarned=true;toast('Browser storage is unavailable. Keep a backup before closing this page.')}}}
function toast(t){$('#studio-toast').textContent=t;$('#studio-toast').className='show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#studio-toast').className='',4800)}
function modal(html){const m=$('#studio-modal');m.innerHTML=`<button class="close" data-act="close-modal" aria-label="Close">×</button>${html}`;m.showModal()}
function closeModal(){$('#studio-modal').close()}
const qById=id=>questions.find(q=>q.id===id);
function record(q){return state.tasks[q.id]??=({steps:{},hintUsed:false,revealed:false,hadError:false,needsReview:false,completed:false,attempt:1})}
function stepRecord(q,index=0){return record(q).steps[index]??=({arrows:[],conditions:['',''],hint:0,solved:false})}
function weakTasks(){return questions.filter(q=>record(q).needsReview)}
function weakEdges(){return edges.filter(e=>['help','notyet'].includes(state.edges[e.id]?.status))}
function weakCount(){return weakTasks().length+weakEdges().length}
function updateWeakBadge(){document.querySelectorAll('[data-weak-count]').forEach(e=>e.textContent=weakCount())}
function shell(content){$('#studio').innerHTML=`<header class="topbar"><a class="brand" href="./index.html"><svg viewBox="0 0 40 44" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 2 37 12v20L20 42 3 32V12Z"/><path d="m20 8 11 7v14l-11 7-11-7V15Z"/></svg><span><strong>Organic Recall</strong><small>STRUCTURE INTO MEMORY</small></span></a><div class="headerlinks"><span class="livebadge">Chapter 19 · visual pilot</span><a href="./practice.html">Basic practice ↗</a><button class="quiet" data-act="about">How it works</button></div></header><main class="page" id="workspace"><section class="hero"><div><span class="eyebrow">A SHORT REVIEW. A CONNECTED UNDERSTANDING.</span><h1>See the reaction. Rebuild the answer.</h1><p>A reaction map, a few careful drawings, and the steps worth another look.<br> Prepared for two focused days before your next organic chemistry test.</p></div><div class="hero-note"><strong>2 days · 150 min</strong>one prepared route through Chapter 19<br>six visual cards · five integrated prompts</div></section><nav class="tabs" aria-label="Exam review sections">${[['map','1 · Reaction map'],['cards','2 · Draw & recall'],['weak','3 · Weak spots'],['paper','4 · Integrated problems'],['lecture','Lecture image cover']].map(([id,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${label}${id==='weak'?`<span class="count" data-weak-count>${weakCount()}</span>`:''}</button>`).join('')}</nav><div id="view-body">${content}</div><footer class="footer"><span>Chapter 19 pilot · source-checked reference steps · small-molecule connectivity checks</span><span>Independent browser app · no GPT or runtime API · <button class="quiet" data-act="export-study">Export study backup</button></span></footer></main>`}
function sources(refs=[],lecture=null){return `<div class="source-links"><span>Source</span>${refs.map(p=>`<a href="./practice.html" data-source-page="${p}" title="Open the textbook index in Basic practice">Textbook PDF p.${p}</a>`).join('')}${lecture?`<button data-lecture-page="${lecture.page}">Lecture ${lecture.file} · PDF p.${lecture.page} / slide ${lecture.slide}</button>`:''}</div>`}
function dayCards(){return plan.map(p=>`<section class="daycard"><span class="time">${p.total}′</span><span class="eyebrow">DAY ${p.day}</span><h3>${p.title}</h3>${p.blocks.map(([t,title,note])=>`<div class="dayblock"><span>${t}</span><div>${title}<small>${note}</small></div></div>`).join('')}</section>`).join('')}
function drawNetwork(){const nodes=new Map(networkNodes.map(n=>[n.id,n]));let lines='';for(const e of edges){const a=nodes.get(e.from),b=nodes.get(e.to),dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,ux=dx/len,uy=dy/len,start={x:a.x+ux*48,y:a.y+uy*26},end={x:b.x-ux*65,y:b.y-uy*27},bend=e.id==='grignard-acid'?-12:e.id==='acid-ester'?-30:e.id==='acid-amide'?20:e.id==='acid-alcohol'?40:0,cx=(start.x+end.x)/2-uy*bend,cy=(start.y+end.y)/2+ux*bend,d=`M${start.x} ${start.y} Q${cx} ${cy} ${end.x} ${end.y}`;lines+=`<g class="network-edge ${state.ui.edge===e.id?'active':''}" data-edge="${e.id}" role="button" tabindex="0" aria-label="Recall ${esc(e.short)}: ${esc(a.label)} to ${esc(b.label)}"><path d="${d}" marker-end="url(#map-head)"/><path d="${d}" class="edge-hit"/><text x="${cx}" y="${cy-8}" text-anchor="middle">${e.short}</text></g>`}return `<svg class="network" viewBox="0 0 840 640" role="img" aria-label="Carboxylic acid reaction network"><defs><marker id="map-head" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M1 1 9 5 1 9" fill="none" stroke="#a3b68e" stroke-width="1.4"/></marker></defs>${lines}${networkNodes.map(n=>`<g class="network-node ${n.id==='acid'?'hub':''}"><rect x="${n.x-83}" y="${n.y-34}" width="166" height="68" rx="9"/><text class="formula" x="${n.x}" y="${n.y-2}" text-anchor="middle">${n.label}</text><text class="node-note" x="${n.x}" y="${n.y+18}" text-anchor="middle">${n.sub}</text></g>`).join('')}</svg>`}
function edgePanel(){const edge=edges.find(e=>e.id===state.ui.edge)||edges[1],r=state.edges[edge.id]||{},from=networkNodes.find(n=>n.id===edge.from),to=networkNodes.find(n=>n.id===edge.to);return `<div class="edgerecall panel"><div class="sectionhead"><div><span class="eyebrow">COVER · RETRIEVE · CONNECT</span><h3>${from.label} → ${to.label}</h3></div><span class="tag">${r.status==='know'?'Recalled':r.status?'Revisit':'Try it cold'}</span></div><div class="formrow"><label for="edge-recall">What reagents, medium and workup make this connection?</label><input id="edge-recall" data-edge-draft="${edge.id}" value="${esc(r.draft||'')}" placeholder="Recall the conditions before revealing them…" autocomplete="off"></div>${r.revealed?`<div class="condition-reveal">${esc(edge.condition)}</div><p class="compatibility"><strong>Compatibility check.</strong> ${esc(edge.compatibility)}</p>`:'<div class="covered"><p>The conditions stay covered until you ask.</p><button class="secondary" data-act="reveal-edge">Reveal this connection</button></div>'}<div class="actions"><button class="secondary" data-edge-status="know">Recalled unaided</button><button class="secondary" data-edge-status="help">Needed a hint</button><button class="secondary" data-edge-status="notyet">Not yet</button>${edge.task?`<button class="primary" data-task="${edge.task}">Draw this route →</button>`:''}</div>${sources(edge.refs)}</div>`}
function renderMap(){shell(`<div class="sectionhead"><h2>The carboxylic acid reaction map</h2><span class="subtle">Select a connection. Keep the conditions covered.</span></div><div class="maplayout"><div><div class="panel network-wrap">${drawNetwork()}<div class="mapcaption"><span><strong>Carboxylic acids connect the chapter.</strong> Follow carbon count, reactivity and workup.</span><span>Scroll horizontally on smaller screens.</span></div></div><div id="edge-panel">${edgePanel()}</div></div><aside class="plan-side">${dayCards()}<div class="scopebox"><strong>Prepared scope, not another planning job.</strong><br> This pilot follows textbook §19-6–19-12 and your two Chapter 19 lectures. Classroom markings guide emphasis; they are not measured exam-frequency data.<br><button class="quiet" data-view="cards">Start the six visual cards →</button></div></aside></div>`)}
function taskStatus(q){const r=record(q);return r.completed?(r.needsReview?'Complete · revisit':'Recalled unaided'):r.needsReview?'Needs another look':'Not tried yet'}
function card(q){return `<button class="taskcard" data-task="${q.id}"><div class="sectionhead" style="margin:0"><span class="tasknum">${q.number}</span><span class="tag ${record(q).needsReview?'warn':''}">${q.kind==='mechanism'?'Electron arrows':q.kind==='reagents'?'Ordered conditions':q.kind==='synthesis'?'Short synthesis':'Edit the product'}</span></div><h3>${q.title}</h3><div class="mini">${q.source?moleculeSVG(q.source):q.steps?moleculeSVG(q.steps[0].source):`<span class="given-label">${esc(q.sourceLabel||'')}</span>`}</div><p>${q.topic} · ${q.steps?.length||1} ${q.steps?'frames':'card'} · about ${q.minutes} min</p><div class="bottom"><span>${taskStatus(q)}</span><span>Open workspace ↗</span></div></button>`}
function renderCards(){shell(`<div class="sectionhead"><div><span class="eyebrow">NO OPTIONS TO RECOGNIZE. BUILD YOUR OWN ANSWER.</span><h2 style="margin-top:6px">Six visual recall cards</h2></div><span class="subtle">Structures and conditions stay hidden until requested.</span></div><div class="gridcards">${questions.map(card).join('')}</div><div class="paperintro" style="margin-top:23px"><strong>A small, bounded drawing pilot.</strong> Products and intermediates are checked by connectivity and formal charge, not layout. Mechanism checks only cover the labelled local reference steps supplied here. Unsupported query/stereo features receive a scope message instead of a guessed grade.</div>`)}
function renderWeak(){const qt=weakTasks(),ee=weakEdges();shell(`<div class="sectionhead"><div><span class="eyebrow">SPEND THE SECOND PASS WHERE IT HELPS.</span><h2 style="margin-top:6px">Your next short review</h2></div><span class="subtle">Hints, revealed answers and unsuccessful checks add items here.</span></div>${!qt.length&&!ee.length?`<div class="empty"><h3>Nothing flagged yet.</h3><p>Work through the map or a drawing card. The points that need help collect themselves here.</p><button class="primary" data-view="cards">Open the visual cards</button></div>`:`${qt.length?`<div class="gridcards">${qt.map(q=>`<article class="taskcard"><span class="tag warn">${q.topic}</span><h3>${q.title}</h3><p>${record(q).revealed?'You opened the reference answer.':record(q).hintUsed?'You needed a hint.':'A check found something to revisit.'}</p><div class="actions"><button class="primary" data-cold="${q.id}">Cold retry</button><button class="quiet" data-task="${q.id}">Review saved drawing</button></div></article>`).join('')}</div>`:''}${ee.length?`<div class="panel" style="margin-top:23px"><h3>Reaction connections to recall again</h3>${ee.map(e=>`<div class="sectionhead" style="padding-top:17px;margin:0"><span>${networkNodes.find(n=>n.id===e.from).label} → ${networkNodes.find(n=>n.id===e.to).label}</span><button class="secondary" data-recall-edge="${e.id}">Cover & recall</button></div>`).join('')}</div>`:''}`}`)}
function renderPaper(){shell(`<div class="sectionhead"><div><span class="eyebrow">FROM ISOLATED REACTIONS TO CONNECTED ANSWERS.</span><h2 style="margin-top:6px">Four or five integrated problems</h2></div><button class="secondary" data-act="export-paper">Export my paper</button></div><div class="paperintro"><strong>Day 2 · about 50 minutes.</strong> Choose four or five prompts relevant to your scope. Give a connected answer: structures, conditions, elementary steps and a brief justification. Notes save automatically; opening a drawing workspace does not lose them. These responses are self-checked against the supplied checklist, not automatically graded as arbitrary synthesis or prose.</div>${integrated.map((p,i)=>{const r=state.paper[p.id]||{};return `<section class="integrated-card"><div class="sectionhead"><h3>${String(i+1).padStart(2,'0')} · ${p.title}</h3><span class="subtle">~${p.minutes} min</span></div><p>${p.prompt}</p><label class="subtle" for="${p.id}">Your route / reasoning / points to check</label><textarea id="${p.id}" data-paper="${p.id}" placeholder="Write your answer first. Use the linked drawing workspace when needed.">${esc(r.text||'')}</textarea><div class="actions">${p.tasks.map(id=>`<button class="secondary" data-task="${id}">${qById(id).topic} workspace ↗</button>`).join('')}<button class="quiet" data-paper-check="${p.id}">${r.check?'Hide':'Reveal'} self-check list</button></div>${r.check?`<ul>${p.checks.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}</section>`}).join('')}`)}
function hintMarkup(q,r){const s=stepRecord(q,stepIndex),n=s.hint||0;return `<h3>Hints stay small.</h3><p>Try your own answer first. Each click reveals just one clue.</p>${q.hints.slice(0,n).map((h,i)=>`<p class="hint-entry">${i+1}. ${h}</p>`).join('')}<button class="quiet" data-act="hint" ${n>=q.hints.length?'disabled':''}>${n>=q.hints.length?'All hints opened':'One more hint'} ${n}/${q.hints.length}</button>`}
function drawTools(){return `<div class="editor-toolbar"><button data-editor-act="undo">Undo</button><button data-editor-act="redo">Redo</button><button data-editor-act="tidy">Tidy layout</button><button data-act="copy-source">Copy this step’s source</button><select id="fragment-template" aria-label="Insert a common fragment"><option value="">Insert fragment…</option><option value="O">Water / oxygen</option><option value="CO">Methanol</option><option value="C#N">Nitrile</option><option value="C1CCCCC1">Cyclohexane</option></select><button data-act="reload-editor">Reload editor</button></div><div class="editor-frame" id="editor-mount"></div><div id="editor-status" class="editor-status" role="status">Opening the bundled structure editor…</div><p class="editor-hint">Use the editor’s atom, bond, charge and template tools. Move or tidy the drawing freely; coordinates and atom numbering are not scored.</p><p class="mobile-only editor-hint">Drawing is designed for a desktop mouse. On a narrow screen, scroll the editor panel horizontally.</p>`}
function conditionsForm(q,s,{kind=q.reagentKind,standalone=false}={}){return `<div class="formrow"><label for="condition-0">${q.kind==='reagents'?q.fields[0]:'Reagents / medium / heat'}</label><input id="condition-0" data-condition="0" value="${esc(s.conditions?.[0]||'')}" placeholder="Enter your conditions…" autocomplete="off"></div><div class="formrow"><label for="condition-1">${q.kind==='reagents'?q.fields[1]:'Ordered workup / isolation (when needed)'}</label><input id="condition-1" data-condition="1" value="${esc(s.conditions?.[1]||'')}" placeholder="Workup follows the reagent stage…" autocomplete="off"></div><button class="quiet" data-act="toggle-palette">${s.palette?'Hide':'Show'} common reagents</button>${s.palette?`<div class="reagent-palette">${['CO2, dry THF','H3O+ / aqueous acid','NaCN, DMF','KCN, DMSO','hot aqueous HCl / reflux','NaOH, water, reflux','then acidify with HCl','LiAlH4, dry THF','SOCl2, heat'].map(x=>`<button data-reagent="${esc(x)}">${esc(x)}</button>`).join('')}</div>`:''}`}
async function leaveTask(){++taskGeneration;if(editor){await editor.capture(false);editor.dispose();editor=null}arrowCanvas?.destroy();arrowCanvas=null;currentTask=null}
async function navigate(next){await leaveTask();view=next;state.ui.view=next;save();if(next==='map')renderMap();else if(next==='cards')renderCards();else if(next==='weak')renderWeak();else if(next==='paper')renderPaper();else if(next==='lecture')renderLecture();window.scrollTo({top:0,behavior:'smooth'})}
async function openTask(id,index=0){const q=qById(id);if(!q)return;await leaveTask();view='cards';currentTask=q;stepIndex=index;state.ui.task=id;state.ui.step=index;save();const r=record(q),s=stepRecord(q,index),step=q.steps?.[index],src=step?.source||q.source;const generation=++taskGeneration;
 shell(`<div class="studio-task-top"><button class="secondary" data-view="cards">← All six cards</button><span class="subtle">Chapter 19 · ${q.topic} · ${taskStatus(q)}</span><button class="quiet" data-cold="${q.id}">Cold retry</button></div><section class="task-title"><span class="eyebrow">${q.number} / 06 · ${q.kind==='mechanism'?'ANNOTATED ELECTRON FLOW':q.kind==='reagents'?'ORDERED CONDITIONS':q.kind==='synthesis'?'A SHORT SYNTHETIC ROUTE':'DRAW THE PRODUCT'}</span><h2>${q.title}</h2><p>${q.prompt}</p>${q.scope?`<p class="scope">${q.scope}</p>`:''}${q.steps?`<nav class="step-strip" aria-label="Mechanism or synthesis frames">${q.steps.map((f,i)=>`<button class="step-chip ${i===index?'active':''}" data-step="${i}" ${i===index?'aria-current="step"':''}><strong>${f.title}</strong>${stepRecord(q,i).mol?moleculeSVG(safeGraph(stepRecord(q,i).mol)||f.source):''}<span>${stepRecord(q,i).solved?'Checked · matches':stepRecord(q,i).mol?'Saved drawing':'Copied source ready'}</span></button>`).join('')}</nav>`:''}</section><div class="task-body"><aside class="task-aside"><div class="given-card"><h3>${step?'This frame starts here':'Given substrate'}</h3>${src?moleculeSVG(src,{caption:'Starting structure'}):`<div class="given-label" style="padding:30px 0">${q.sourceLabel}</div>`}${q.conditions?`<div class="condition">${esc(q.conditions)}</div>`:''}${step?.note?`<p class="scope-note">${step.note}</p>`:''}${sources(q.refs,q.lecture)}</div><div class="hint-card" id="hint-panel">${hintMarkup(q,r)}</div><p class="scope-note">Hints and revealed answers flag this card for a second, cold recall. Drawings and notes save on this device.</p></aside><div class="task-main">${q.kind==='reagents'?`<section class="input-panel"><h3>Supply the ordered conditions</h3><div class="given-reaction"><div class="given-label">${q.sourceLabel}</div><div class="reaction-arrow">→</div>${moleculeSVG(q.target)}</div><div id="conditions-form">${conditionsForm(q,s,{standalone:true})}</div></section>`:`${q.kind==='mechanism'?`<section class="input-panel"><div class="panellead"><h3>1 · Draw the complete electron-pair arrow set</h3><span class="tag"><span id="arrow-count">${s.arrows.length}</span> arrows</span></div><p class="keyboard-note">Drag from an atom lone pair or a bond to an atom / bond. Endpoints snap. You can also click a start then an end; Shift reverses a dragged curve.</p><div class="atom-legend"><span>Green dots · bond anchors</span><span>Two-barbed head · electron pair</span></div><div class="arrow-viewport" id="arrow-mount"></div><div class="arrowtools"><button data-arrow-act="undo">Undo arrow</button><button data-arrow-act="redo">Redo arrow</button><button data-arrow-act="flip">Flip selected curve</button><button data-arrow-act="remove">Delete selected arrow</button><button data-arrow-act="clear">Clear arrows</button><button data-act="check-arrows">Check arrow set only</button></div><div id="arrow-feedback"></div></section>`:''}<section class="input-panel"><div class="panellead"><h3>${q.kind==='mechanism'?'2 · Edit the next intermediate':q.kind==='synthesis'?'Draw the product of this transformation':'Edit the product'}</h3><span class="tag">Ketcher · standalone</span></div>${q.kind==='synthesis'?`<div id="conditions-form">${conditionsForm(q,s,{kind:step.reagentKind})}</div>`:''}${drawTools()}</section>`}<div id="task-feedback">${s.feedback?feedbackMarkup(s.feedback,s.preview):''}</div><div id="reference-answer">${s.answer?answerMarkup(q,step):''}</div><div class="task-controls"><div class="actions"><button class="primary" data-act="check-step">${q.kind==='reagents'?'Check conditions':q.kind==='mechanism'?'Check this whole step':'Check my answer'}</button><button class="secondary" data-act="show-answer">Reveal reference answer</button></div><div class="actions"><span class="autosave" id="save-status">Saved on this device</span>${q.steps&&index<q.steps.length-1?'<button class="primary" data-act="next-step">Copy drawing → next frame</button>':`<button class="secondary" data-view="paper">Integrated problems →</button>`}</div></div></div></div>`);
 if(q.kind==='mechanism')arrowCanvas=new ElectronCanvas($('#arrow-mount'),step.source,s.arrows,arrows=>{s.arrows=arrows;s.solved=false;r.completed=false;$('#arrow-count').textContent=arrows.length;save()});
 if(q.kind!=='reagents'){editor=new StructureEditor($('#editor-mount'),{graph:step?.scaffold||q.source,saved:s,onSave:(snapshot,dirty)=>{if(generation!==taskGeneration)return;Object.assign(s,snapshot);if(dirty){s.solved=false;r.completed=false}save()},onStatus:(text,kind)=>{if(generation!==taskGeneration)return;const el=$('#editor-status');if(el){el.textContent=text;el.className='editor-status '+(kind==='warning'?'warning':'')}}})}
 window.scrollTo({top:0,behavior:'smooth'});
}
function safeGraph(mol){try{return parseMol(mol)}catch{return null}}
function feedbackMarkup(f,preview){return `<section class="feedback ${f.correct?'correct':''}" role="status"><h4>${f.correct?'✓ Matches this annotated answer':'A few specific points to revisit'}</h4><p>${esc(f.message)}</p>${f.issues?.length?`<ul>${f.issues.map(x=>`<li>${esc(typeof x==='string'?x:x.message)}</li>`).join('')}</ul>`:''}${preview?`<p>Atom numbers below refer only to this saved drawing.</p>${moleculeSVG(preview,{labels:true,caption:'Your current structure, with atom numbers'})}`:''}</section>`}
function answerMarkup(q,step){const target=step?.targets?.[0]||q.targets?.[0];return `<section class="answer-panel"><h4>Reference answer · ${step?.title||q.targetName||q.topic}</h4><p>${esc(step?.answer||q.explanation)}</p>${q.kind==='reagents'||q.kind==='synthesis'?`<ol>${(step?.model||q.model||[]).filter(Boolean).map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:''}${q.kind==='mechanism'?`<p>The paired arrows: ${step.arrows[0].map(a=>`${a.from} → ${a.to}`).join('; ')}.</p>`:''}${target?moleculeSVG(target,{labels:q.kind==='mechanism',caption:'Annotated answer structure'}):''}<p>This is a source-checked reference for the stated scope. Alternative unannotated mechanisms or syntheses require manual comparison.</p>${sources(q.refs,q.lecture)}</section>`}
async function checkCurrent(arrowsOnly=false){const q=currentTask;if(!q)return;const r=record(q),s=stepRecord(q,stepIndex),step=q.steps?.[stepIndex];if(arrowsOnly){const f=checkArrowSet(s.arrows,step.arrows);$('#arrow-feedback').innerHTML=feedbackMarkup(f);if(!f.correct){r.hadError=true;r.needsReview=true;save();updateWeakBadge()}return}let f,preview=null;try{if(q.kind==='reagents'){const a=checkReagents(s.conditions,q.reagentKind);f={correct:a.correct,message:a.message,issues:a.issues}}else{const drawn=await editor.drawing();preview=drawn;const structure=compareGraphs(drawn,step?.targets||q.targets),checks=[structure];if(q.kind==='mechanism')checks.push(checkArrowSet(s.arrows,step.arrows));if(q.kind==='synthesis')checks.push(checkReagents(s.conditions,step.reagentKind));f={correct:checks.every(x=>x.correct),message:checks.every(x=>x.correct)?'Your structure and required conditions / electron movements match this annotated frame.':'Use the feedback below, then edit the reaction centre or companion electron movement.',issues:checks.flatMap(x=>x.issues||[])}}s.feedback=f;s.preview=preview;s.solved=f.correct;if(!f.correct){r.hadError=true;r.needsReview=true}const complete=(q.steps||[{}]).every((_,i)=>stepRecord(q,i).solved);r.completed=complete;if(complete)r.needsReview=!!(r.hintUsed||r.revealed||r.hadError);$('#task-feedback').innerHTML=feedbackMarkup(f,preview);save();updateWeakBadge();if(f.correct)toast(complete?'This card is complete. Try it cold again if you used help.':'This elementary frame matches. Continue when ready.')}catch(e){toast(e.message)}}
async function nextStep(){const q=currentTask;if(!q?.steps||stepIndex>=q.steps.length-1)return;const shot=await editor?.capture(false),next=stepRecord(q,stepIndex+1);if(!next.mol&&shot){let g=parseMol(shot.mol);const now=q.steps[stepIndex].targets[0],after=q.steps[stepIndex+1].source;for(const atom of after.atoms.filter(a=>!now.atoms.some(n=>n.id===a.id))){const xs=g.atoms.map(a=>a.x),ys=g.atoms.map(a=>a.y);g.atoms.push({...clone(atom),id:'added-'+atom.id,x:Math.max(...xs)+100,y:Math.min(...ys)-40})}next.mol=writeMol(g);next.ket=null;save()}await openTask(q.id,stepIndex+1)}
async function coldRetry(id){const q=qById(id);if(!q)return;await leaveTask();const old=record(q),attempt=(old.attempt||1)+1;state.tasks[id]={steps:{},hintUsed:false,revealed:false,hadError:false,needsReview:true,completed:false,attempt};save();await openTask(id,0);toast('A fresh scaffold is ready. Previous hints are covered for this cold retry.')}
function renderLecture(){shell(`<div class="sectionhead"><div><span class="eyebrow">YOUR LECTURE IMAGE, WITH JUST THE ANSWER COVERED.</span><h2 style="margin-top:6px">Look, cover, and reconstruct</h2></div><button class="primary" data-act="choose-lecture">Choose lecture PDF</button></div><div class="lecture-layout"><aside class="lecture-instructions"><h3>Use the actual slide locally.</h3><ol><li>Choose a text or image PDF from your device.</li><li>Open the page you want to recall.</li><li>Drag rectangles over products, conditions or intermediate structures.</li><li>Recall first; click an individual cover or reveal all when ready.</li></ol><p>Only your cover positions and page number are saved. The PDF and slide image stay in this browser, and are not published or uploaded.</p><div class="scopebox" style="margin-top:13px"><strong>Prepared Chapter 19 reference</strong><br> The HVZ exchange slide is original slide 32, PDF page 35 in lecture 2.<br><button class="quiet" data-task="mechanism-hvz">Open its annotated drawing task →</button></div></aside><div><div class="lecture-tools"><span>${lectureFile?esc(lectureFile.name):'No local PDF selected'}</span><label for="lecture-page">PDF page</label><input id="lecture-page" type="number" min="1" max="${lectureDoc?.numPages||250}" value="${lecturePage}"><button data-act="render-lecture">Open page</button><button data-act="toggle-mask-mode">${lectureDrawing?'Drawing covers: on':'Drawing covers: off'}</button><button data-act="toggle-covers">${lectureRevealed?'Cover answers':'Reveal all covers'}</button><button data-act="clear-masks">Clear page covers</button></div><div class="lecture-image" id="lecture-image">${lectureDoc?'<canvas id="lecture-canvas"></canvas><div class="mask-layer" id="mask-layer"></div>':'<div class="lecture-nudge">Choose a local lecture PDF to use the actual slide.<br> It can contain images; OCR is not required for visual covering.</div>'}</div><p class="page-meta">Use file-page numbers, not printed slide numbers. Reopen the PDF after a refresh to restore its image.</p></div></div>`);if(lectureDoc)drawLecturePage()}
async function pdfLib(){if(!pdfLib.promise)pdfLib.promise=import('./vendor/pdf.mjs').then(lib=>{lib.GlobalWorkerOptions.workerSrc='./vendor/pdf.worker.mjs';return lib});return pdfLib.promise}
async function chooseLecture(file){if(!file||lectureLoading)return;if(file.size>50*1024*1024)return toast('Use a lecture PDF up to 50 MB.');lectureLoading=true;toast('Opening the local lecture image…');try{const lib=await pdfLib(),bytes=new Uint8Array(await file.arrayBuffer());const task=lib.getDocument({data:bytes,cMapUrl:'./vendor/cmaps/',cMapPacked:true,standardFontDataUrl:'./vendor/standard_fonts/',wasmUrl:'./vendor/wasm/',isEvalSupported:false});const doc=await task.promise;if(doc.numPages>250){await doc.destroy();throw Error('Please split lecture PDFs longer than 250 pages.')}if(lectureDoc)await lectureDoc.destroy();lectureDoc=doc;lectureFile=file;lecturePage=Math.min(lecturePage,doc.numPages);view='lecture';await leaveTask();renderLecture()}catch(e){toast(e.name==='PasswordException'?'Choose an unlocked PDF.':'Could not open this lecture: '+e.message)}finally{lectureLoading=false}}
function maskKey(){return lectureFile?`${lectureFile.name}|${lectureFile.size}|${lecturePage}`:null}
function pageMasks(){const key=maskKey();return key?(state.lectureMasks[key]??=[]):[]}
function renderMasks(){const el=$('#mask-layer');if(!el)return;el.innerHTML=pageMasks().map((m,i)=>`<div class="occlusion ${lectureRevealed||m.revealed?'revealed':''}" data-mask="${i}" style="left:${m.x*100}%;top:${m.y*100}%;width:${m.w*100}%;height:${m.h*100}%" role="button" tabindex="0" aria-label="${m.revealed?'Hide':'Reveal'} covered region ${i+1}">Recall first</div>`).join('');}
async function drawLecturePage(){if(!lectureDoc||!$('#lecture-canvas'))return;try{lecturePage=Math.max(1,Math.min(lectureDoc.numPages,Number($('#lecture-page')?.value)||lecturePage));const page=await lectureDoc.getPage(lecturePage),canvas=$('#lecture-canvas'),viewPort=page.getViewport({scale:1.5});canvas.width=viewPort.width;canvas.height=viewPort.height;if(lectureRenderTask)lectureRenderTask.cancel();lectureRenderTask=page.render({canvasContext:canvas.getContext('2d'),viewport:viewPort});await lectureRenderTask.promise;renderMasks();const layer=$('#mask-layer');let draft=null;const point=e=>{const box=layer.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-box.left)/box.width)),y:Math.max(0,Math.min(1,(e.clientY-box.top)/box.height))}};layer.onpointerdown=e=>{if(e.target.closest('[data-mask]')||!lectureDrawing)return;draft={start:point(e)};layer.setPointerCapture(e.pointerId);e.preventDefault();const box=document.createElement('div');box.className='occlusion draft';layer.append(box);draft.box=box};layer.onpointermove=e=>{if(!draft)return;const p=point(e),x=Math.min(p.x,draft.start.x),y=Math.min(p.y,draft.start.y),w=Math.abs(p.x-draft.start.x),h=Math.abs(p.y-draft.start.y);Object.assign(draft,{x,y,w,h});Object.assign(draft.box.style,{left:x*100+'%',top:y*100+'%',width:w*100+'%',height:h*100+'%'})};layer.onpointerup=()=>{if(!draft)return;if(draft.w>.025&&draft.h>.025)pageMasks().push({x:draft.x,y:draft.y,w:draft.w,h:draft.h,revealed:false});draft=null;save();renderMasks()};layer.onpointercancel=()=>{draft=null;renderMasks()}}catch(e){if(e.name!=='RenderingCancelledException')toast('Could not render that page: '+e.message)}}
function exportFile(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function about(){modal(`<h2>A short path from recognition to recall</h2><p>This Chapter 19 pilot adds six drawing / conditions cards, an annotated reaction map, five integrated prompts and a 150-minute two-day plan. The original 236-question practice bank remains under Basic practice.</p><p>Structure editing uses the bundled <a href="https://github.com/epam/ketcher" target="_blank" rel="noopener">EPAM Ketcher 3.18.0 standalone editor</a>. Its chemistry engine runs in your browser. Electron-pushing arrows use a separate SVG layer with atom/bond anchors; ordinary reaction arrows are not counted as electron movements.</p><p>Products and selected intermediates use small-molecule graph isomorphism with formal charge and bond-order checks. Normal hydrogen expansion is normalized for product questions; explicitly labelled hydrogens are retained in the proton-tracking mechanisms. Stereochemistry, aromatic queries, arbitrary mechanisms and unrestricted synthetic routes are outside this pilot’s automatic grading scope.</p><p>The HVZ task follows the carbonyl-oxygen route shown on lecture 2 PDF page 35 and accepts its two resonance representations. This is a source-checked annotated local pathway, not a claim that every other pathway is chemically impossible.</p><p>Hints, revealed answers and failed checks create a short weak-point queue. All drawings, arrows, notes and covers are saved only on this browser. Your local lecture PDFs are not uploaded. Reopen them after refreshing if you want to view their images.</p><div class="actions"><button class="primary" data-act="close-modal">Back to the workspace</button><button class="secondary" data-act="export-study">Export study backup</button></div>`)}
document.addEventListener('input',e=>{const d=e.target.dataset;if(d.edgeDraft){state.edges[d.edgeDraft]??={};state.edges[d.edgeDraft].draft=e.target.value;save()}if(d.condition!==undefined&&currentTask){stepRecord(currentTask,stepIndex).conditions[+d.condition]=e.target.value;stepRecord(currentTask,stepIndex).solved=false;record(currentTask).completed=false;save()}if(d.paper){state.paper[d.paper]??={};state.paper[d.paper].text=e.target.value;save()}});
document.addEventListener('focusin',e=>{if(e.target.dataset.condition!==undefined)focusedCondition=+e.target.dataset.condition});
document.addEventListener('change',e=>{if(e.target.id==='fragment-template'&&e.target.value){editor?.fragment(e.target.value);e.target.value=''}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-edge]')){e.preventDefault();selectEdge(e.target.dataset.edge)}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-mask]')){e.preventDefault();toggleMask(+e.target.dataset.mask)}});
function selectEdge(id){state.ui.edge=id;save();if(view!=='map')navigate('map');else{$('#edge-panel').innerHTML=edgePanel();document.querySelectorAll('[data-edge]').forEach(n=>n.classList.toggle('active',n.dataset.edge===id))}}
function toggleMask(i){const m=pageMasks()[i];if(!m)return;m.revealed=!m.revealed;save();renderMasks()}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-edge],[data-mask],a[data-source-page]');if(!b)return;const d=b.dataset;if(d.view){await navigate(d.view);return}if(d.task){await openTask(d.task);return}if(d.cold){await coldRetry(d.cold);return}if(d.step!==undefined&&currentTask){await openTask(currentTask.id,+d.step);return}if(d.edge){selectEdge(d.edge);return}if(d.edgeStatus){const r=state.edges[state.ui.edge]??={};r.status=d.edgeStatus;save();$('#edge-panel').innerHTML=edgePanel();updateWeakBadge();return}if(d.recallEdge){state.ui.edge=d.recallEdge;state.edges[d.recallEdge]??={};state.edges[d.recallEdge].revealed=false;await navigate('map');return}if(d.editorAct){await editor?.action(d.editorAct);return}if(d.arrowAct){arrowCanvas?.[d.arrowAct]?.();return}if(d.reagent){const el=$('#condition-'+focusedCondition)||$('#condition-0');if(el){el.value=el.value?el.value+'; '+d.reagent:d.reagent;el.dispatchEvent(new Event('input',{bubbles:true}))}return}if(d.paperCheck){state.paper[d.paperCheck]??={};state.paper[d.paperCheck].check=!state.paper[d.paperCheck].check;save();renderPaper();return}if(d.mask!==undefined){toggleMask(+d.mask);return}if(d.lecturePage){lecturePage=+d.lecturePage;await navigate('lecture');return}if(d.sourcePage){e.preventDefault();modal(`<h2>Textbook PDF page ${d.sourcePage}</h2><p>References use the supplied sixth-edition textbook’s file-page sequence. In Basic practice, choose “Link textbook”, then use the textbook index or a question’s source link. Your local book stays in your browser.</p><div class="actions"><a class="primary" href="./practice.html">Open Basic practice</a><button class="secondary" data-act="close-modal">Keep drawing</button></div>`);return}switch(d.act){case'close-modal':closeModal();break;case'about':about();break;case'reveal-edge':state.edges[state.ui.edge]??={};state.edges[state.ui.edge].revealed=true;state.edges[state.ui.edge].status='help';save();$('#edge-panel').innerHTML=edgePanel();updateWeakBadge();break;case'hint':{if(!currentTask)return;const r=record(currentTask),s=stepRecord(currentTask,stepIndex);s.hint=Math.min(currentTask.hints.length,(s.hint||0)+1);r.hintUsed=true;r.needsReview=true;$('#hint-panel').innerHTML=hintMarkup(currentTask,r);save();updateWeakBadge();break}case'copy-source':await editor?.load(currentTask.steps?.[stepIndex]?.scaffold||currentTask.source);break;case'reload-editor':if(currentTask)await openTask(currentTask.id,stepIndex);break;case'check-arrows':await checkCurrent(true);break;case'check-step':await checkCurrent(false);break;case'show-answer':{const q=currentTask;if(!q)return;const r=record(q),s=stepRecord(q,stepIndex);r.revealed=true;r.needsReview=true;s.answer=true;$('#reference-answer').innerHTML=answerMarkup(q,q.steps?.[stepIndex]);save();updateWeakBadge();break}case'next-step':await nextStep();break;case'toggle-palette':{const q=currentTask;if(!q)return;const s=stepRecord(q,stepIndex);s.palette=!s.palette;$('#conditions-form').innerHTML=conditionsForm(q,s);save();break}case'choose-lecture':$('#lecture-file').click();break;case'render-lecture':drawLecturePage();break;case'toggle-mask-mode':lectureDrawing=!lectureDrawing;b.textContent=lectureDrawing?'Drawing covers: on':'Drawing covers: off';break;case'toggle-covers':lectureRevealed=!lectureRevealed;b.textContent=lectureRevealed?'Cover answers':'Reveal all covers';renderMasks();break;case'clear-masks':if(maskKey()){state.lectureMasks[maskKey()]=[];save();renderMasks()}break;case'export-study':if(editor)await editor.capture(false);exportFile('Organic-Recall-Visual-Study.json',JSON.stringify(state,null,2));break;case'export-paper':exportFile('Organic-Recall-Integrated-Paper.md','# Chapter 19 integrated practice\n\n'+integrated.map((p,i)=>`## ${i+1}. ${p.title}\n\n${p.prompt}\n\n${state.paper[p.id]?.text||'[No notes yet]'}\n\nSelf-check:\n${p.checks.map(x=>'- '+x).join('\n')}`).join('\n\n'),'text/markdown;charset=utf-8');break}});
$('#lecture-file').addEventListener('change',e=>{chooseLecture(e.target.files[0]);e.target.value=''});
window.addEventListener('pagehide',()=>{editor?.capture(false);save()});
renderMap();
